// Integrity and honesty checks for the portfolio-demo snapshots. No backend or network needed.
//
// Usage:
//   node scripts/check-demo-data.mjs                 check public-demo/demo
//   node scripts/check-demo-data.mjs --dist dist     also check that a built dist/ ships exactly those files
//
// The snapshots are generated by backend/scripts/build_demo_data.py (which also has a --check mode
// that re-runs the real backend pipeline and compares the numbers). This script covers what can be
// verified from the files alone: hashes, schema, redaction, and that synthetic data is labelled as such.

import { createHash } from 'node:crypto'
import { existsSync, readdirSync, readFileSync, statSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = join(dirname(fileURLToPath(import.meta.url)), '..')
const demoDir = join(root, 'public-demo', 'demo')
const fixtureDat = join(root, '..', '..', 'backend', 'tests', 'fixtures', 'Fe2CoGe_annealed_48hrs_900C_M_H_M_T.dat')

const failures = []
let checks = 0
function check(ok, message) {
  checks += 1
  if (!ok) failures.push(message)
}

function* walk(dir) {
  for (const entry of readdirSync(dir)) {
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) yield* walk(full)
    else yield full
  }
}

const sha256 = (buffer) => createHash('sha256').update(buffer).digest('hex')
const readJson = (path) => JSON.parse(readFileSync(path, 'utf8'))

function* keysOf(value) {
  if (Array.isArray(value)) {
    for (const item of value) yield* keysOf(item)
  } else if (value && typeof value === 'object') {
    for (const [key, child] of Object.entries(value)) {
      yield key
      yield* keysOf(child)
    }
  }
}

// ---------------------------------------------------------------- source files
check(existsSync(demoDir), `Missing ${relative(root, demoDir)}. Run: cd backend && python -m scripts.build_demo_data`)
if (failures.length === 0) {
  const manifest = readJson(join(demoDir, 'manifest.json'))
  check(manifest.schema_version === 1, 'manifest.schema_version must be 1')

  // 1. Every snapshot file is listed with a matching hash, and nothing else is shipped.
  const listed = new Set(Object.keys(manifest.files))
  const onDisk = [...walk(demoDir)]
    .map((file) => relative(demoDir, file).split('\\').join('/'))
    .filter((rel) => rel !== 'manifest.json')
  for (const rel of onDisk) check(listed.has(rel), `${rel} is not listed in manifest.files`)
  for (const [rel, hash] of Object.entries(manifest.files)) {
    const file = join(demoDir, rel)
    check(existsSync(file), `${rel} is listed in the manifest but missing`)
    if (existsSync(file)) check(sha256(readFileSync(file)) === hash, `${rel} does not match its manifest hash`)
  }
  check(
    onDisk.every((rel) => rel.endsWith('.json')),
    'Only .json snapshots may be published (no raw instrument files)',
  )
  check(manifest.raw_instrument_files_published === false, 'manifest must state that raw instrument files are not published')

  // 2. No instrument identifiers, in any file.
  const serialValues = new Set()
  if (existsSync(fixtureDat)) {
    const header = readFileSync(fixtureDat, 'latin1').split(/\r?\n/).slice(0, 80)
    for (const line of header) {
      const match = /^INFO,([^,]+),[A-Z_]*SERIAL_NUMBER\s*$/.exec(line)
      if (match && match[1].trim().length >= 3) serialValues.add(match[1].trim())
    }
    check(serialValues.size > 0, 'The fixture header no longer lists serial numbers; update this check')
  } else {
    console.log('note: backend fixture not found; skipping the serial-value scan (key names are still checked)')
  }
  for (const rel of onDisk.concat('manifest.json')) {
    const text = readFileSync(join(demoDir, rel), 'utf8')
    check(!/"[A-Z_]*SERIAL_NUMBER"\s*:/.test(text), `${rel} contains a *_SERIAL_NUMBER field`)
    for (const value of serialValues) {
      const pattern = /^\d+$/.test(value) ? `"${value}"` : value
      check(!text.includes(pattern), `${rel} contains an instrument identifier from the original header`)
    }
  }

  // 3. Samples, experiments and labelling.
  const samples = readJson(join(demoDir, 'samples.json'))
  check(Array.isArray(samples) && samples.length === manifest.samples.length, 'samples.json must list every sample in the manifest')
  const featuredSample = manifest.samples.find((s) => s.id === manifest.featured.sample_id)
  check(featuredSample?.data_kind === 'real-measurement', 'The featured sample must be the real measurement')

  for (const entry of manifest.samples) {
    const detail = readJson(join(demoDir, 'samples', `${entry.id}.json`))
    check(detail.demo?.data_kind === entry.data_kind, `${entry.id}: sample data_kind differs from the manifest`)
    const experimentIds = detail.experiments.map((e) => e.id)
    check(experimentIds.includes(entry.experiment_id), `${entry.id}: experiment ${entry.experiment_id} is not listed on the sample`)

    const experiment = readJson(join(demoDir, 'experiments', `${entry.experiment_id}.json`))
    const analysis = experiment.analysis_json
    const source = manifest.sources[entry.experiment_id]
    check(experiment.demo?.data_kind === entry.data_kind, `${entry.experiment_id}: experiment data_kind differs from the manifest`)
    check(experiment.demo?.source_sha256 === source?.sha256, `${entry.experiment_id}: provenance hash differs from the manifest`)

    if (entry.data_kind === 'synthetic') {
      check(experiment.experiment_type === 'xrd', 'The synthetic record must be the XRD pattern')
      check(/not a laboratory measurement/i.test(experiment.demo.label), 'Synthetic experiment label must say it is not a laboratory measurement')
      check(/^SYNTHETIC/.test(detail.notes ?? ''), 'Synthetic sample notes must start with SYNTHETIC')
      check(detail.formula === null, 'The synthetic XRD sample must not be attributed to a material')
      const { two_theta_deg: tt, intensity } = analysis.series
      check(tt.length === intensity.length && tt.length === analysis.summary.point_count, 'XRD series length differs from summary.point_count')
    } else {
      check(experiment.experiment_type === 'magnetometry', 'The real record must be the magnetometry measurement')
      check(!/synthetic/i.test(JSON.stringify(experiment.demo)), 'The real measurement must not be labelled synthetic')
      check(analysis.mh_analyses.length === analysis.summary.mh_segment_count, 'M-H analysis count differs from summary')
      check(analysis.segmentation.segments.length === analysis.segmentation.segment_count, 'Segment count differs from segmentation.segment_count')
      check(analysis.metadata.SAMPLE_MATERIAL === 'Fe2CoGe', 'Unexpected sample material in the instrument metadata')
    }
    check(experiment.demo.modifications.every((m) => typeof m === 'string' && m.length > 0), `${entry.experiment_id}: modifications must be described`)

    // 4. No claims the pipeline does not make.
    for (const key of keysOf(experiment)) {
      check(!/^(ms|tc|saturation_magnetization|curie_temperature|ms_emu)$/i.test(key), `${entry.experiment_id}: unexpected key "${key}" (max|M| must not be labelled Ms; no Tc)`)
    }
  }
  check(
    manifest.redactions.removed_metadata_keys.every((key) => key.endsWith('_SERIAL_NUMBER')),
    'Only serial-number fields may be redacted',
  )
  const real = readJson(join(demoDir, 'experiments', `${manifest.featured.experiment_id}.json`))
  check(
    real.demo.modifications.some((m) => manifest.redactions.removed_metadata_keys.every((key) => m.includes(key))),
    'The redaction must be disclosed in the experiment provenance',
  )

  // 5. Copilot replies are stored-record readouts, not model output.
  const copilot = readJson(join(demoDir, 'copilot.json'))
  check(copilot.status.llmAvailable === false, 'Demo Copilot status must report no language model')
  for (const [key, reply] of Object.entries(copilot.replies)) {
    check(reply.source === 'stored-records' && reply.llmAvailable === false, `Copilot reply ${key} must be a stored-record readout`)
    check(!/Ms\s*=|saturation magnetization\s*[:=]\s*\d/i.test(reply.answer), `Copilot reply ${key} presents a value as saturation magnetization`)
  }
  check(Object.keys(copilot.replies).length === manifest.samples.length + 1, 'Copilot needs one reply per sample plus an overview')

  // 6. Materials Project attribution.
  const materials = readJson(join(demoDir, 'materials.json'))
  check(materials.source.license === 'CC BY 4.0' && /^\d{4}-\d{2}-\d{2}$/.test(materials.source.retrieved), 'Materials data needs licence and retrieval date')
  check(materials.formulas.length > 0 && materials.formulas.every((f) => materials.entries[f]), 'materials.formulas must all have entries')
}

// ----------------------------------------------------------------- built output
const distIndex = process.argv.indexOf('--dist')
if (distIndex !== -1) {
  const distDir = join(root, process.argv[distIndex + 1] ?? 'dist')
  check(existsSync(distDir), `No build output at ${relative(root, distDir)}`)
  if (existsSync(distDir)) {
    const shipped = [...walk(distDir)].map((f) => relative(distDir, f).split('\\').join('/'))
    check(shipped.includes('index.html'), 'dist/index.html is missing')
    check(!shipped.some((f) => /\.(dat|xy|cif|env)$|(^|\/)\.env/i.test(f)), 'dist contains a raw data or environment file')
    for (const rel of Object.keys(JSON.parse(readFileSync(join(demoDir, 'manifest.json'), 'utf8')).files).concat('manifest.json')) {
      const built = join(distDir, 'demo', rel)
      check(existsSync(built), `dist/demo/${rel} was not built`)
      if (existsSync(built)) {
        check(sha256(readFileSync(built)) === sha256(readFileSync(join(demoDir, rel))), `dist/demo/${rel} differs from the snapshot`)
      }
    }
    const indexHtml = readFileSync(join(distDir, 'index.html'), 'utf8')
    // The Render blueprint's CSP allow-lists the inline theme script by hash; keep them in step.
    const inline = [...indexHtml.matchAll(/<script(?![^>]*\bsrc=)[^>]*>([\s\S]*?)<\/script>/g)].map((m) => m[1])
    const blueprint = join(root, '..', '..', 'render.demo.yaml')
    if (existsSync(blueprint)) {
      const yaml = readFileSync(blueprint, 'utf8')
      for (const script of inline) {
        const hash = createHash('sha256').update(script).digest('base64')
        check(yaml.includes(`'sha256-${hash}'`), `render.demo.yaml CSP is missing the hash of the inline script (sha256-${hash})`)
      }
    }
    check(!/https?:\/\/(?!www\.w3\.org)[^"' ]*\/api\b/.test(indexHtml), 'index.html references an API host')
  }
}

if (failures.length > 0) {
  console.error('Demo data check FAILED:')
  for (const failure of [...new Set(failures)]) console.error(`  - ${failure}`)
  process.exit(1)
}
console.log(`Demo data check OK: ${checks} checks passed${distIndex !== -1 ? ' (including the built output)' : ''}.`)
